stmt='For every w>=4,m>=0, start with the all-zero point-selector edit of h_w*h_2 and the prescribed A095 support-completed source-spectrum reference. After any finite adaptive wide-only tree, query a narrow coordinate at its edited-path leaf, resetting only child0 to the canonical h_t*h_1 reference mixed with eta times full uniform for eta in[0,1/4]. Query the remaining narrow coordinate inside that reset child and reset only child00 to the canonical -h_t reference, t=w-d. The complete final query-release-plus-terminal ledger, and even the conservative booking of both positive signed reset excesses against the original quota, is below4 I_root-3/256. Every old debit, complementary terminal and full inherited H+KL remains retained; an independent untouched terminal remains additive outside the core bank.'
hyp=['Uniform physical cube and ideal bits; actual labelled point0 edit','No selector/padding/independent-terminal query; no repeated coordinate on a path','Prescribed references and normalized actual physical-child posterior transport; no renewed quota','h_0=-1; t0,m0 fresh point spectrum allows a zero old reference atom of zero true mass']
claim=dict(claim_id='A095-TWO-NARROW-RESETS-SAME-RATE4-BANK',version=1,exact_statement=stmt,hypotheses=hyp,statement_sha256=hashlib.sha256(json.dumps({'exact_statement':stmt,'hypotheses':hyp},sort_keys=True,separators=(',',':')).encode()).hexdigest(),contributors=['A095/account03'],proof_source={'path':str(R/'DERIVATION.md'),'sha256':sh(R/'DERIVATION.md'),'sections':'1-4'},proof_dependencies=[{'claim_id':'A095-UNBOUNDED-WIDTH-SIGNED-PROFILE-HISTORY','version':1,'scope':'accepted root/reference/edge chain'},{'claim_id':review['claim_id'],'version':review['version'],'scope':'independently reconstructed first narrow reset price'}],review_records=[],status='ANALYTIC_AUTHOR_PROOF_EXACT_FINITE_CERTIFICATES_REVIEW_PENDING',supersedes=[],refutes=[],first_unproved_line='None within scope; arbitrary-source reference and further prescribed-reset payment remain open.',next_consumers=['A094','A086','A096','A097','A099'])
put(R/'CLAIMS.json',[claim,review])
