rp=R/'REPORT.md';txt=rp.read_text(encoding='utf-8');txt=txt.replace('out/EXACT_RESULTS.json is authoritative for final totals, signs, runtime and exact outward interval receipts;',f'Final PASS: {n} exact assertions on58 histories in{runtime}s; second excess is certified positive in{pos} and negative in{neg} cases (remaining cases include exact neutral boundaries). out/EXACT_RESULTS.json supplies exact outward interval receipts;');rp.write_text(txt,encoding='utf-8')
fields=set(protocol['required_per_run']['progress_fields']);fields.remove('packet_ids (one primary ID, for compatibility)');fields.add('packet_ids');assert set(progress)==fields
for c in [claim,review]:assert set(c)==set(protocol['required_per_run']['claim_fields'])
assert (R/'PROGRESS.json').read_bytes()==(R/'PACKET_DELTA.json').read_bytes()
assert len((A/'STATUS.md').read_text(encoding='utf-8').splitlines())==2
assert all(s in txt for s in protocol['required_per_run']['report_fields']);assert '## Universal bridge' in txt
put(R/'out/SCHEMA_VALIDATION.json',{'status':'PASS','assertions':n,'histories':58,'exact_field_sets':True,'progress_delta_identical':True,'full_fei':'OPEN'})
out=[]
for p in list(R.rglob('*'))+[A/'STATUS.md',A/'WORKLOG.md',A/'LEARNED.md']:
    if p.is_file() and p.name!='PERSISTENCE_RECEIPTS.json':assert p.stat().st_size<20_000_000;out.append({'path':str(p),'bytes':p.stat().st_size,'sha256':sh(p)})
put(R/'out/PERSISTENCE_RECEIPTS.json',out)
print(json.dumps({'status':'PASS','assertions':n,'histories':58,'positive_second':pos,'negative_second':neg,'files':len(out)}))
